{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In humans, SKF 38393 was found unmetabolised in CSF and produced centrally mediated prolactin stimulation, directly demonstrating BBB penetration; this benzazepine shares the secondary amine and phenolic substitution pattern of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In rats, salsolinol was detected by microdialysis in the neostriatum at 100 nM after systemic administration, confirming brain entry; its tetrahydroisoquinoline amine/phenol framework is closely analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In rats, HMTIC reached 0.3-7% of dose in brain after peripheral administration, with evidence for LAT-mediated uptake; this supports CNS access for a small basic aromatic amine similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Fluorescein showed no brain fluorescence in mice, indicating impermeable BBB; however, it is a large anionic dye lacking the query's basic amine, so this negative evidence is less transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Coumestrol had very low brain-to-plasma ratio in mice due to Bcrp efflux; this polyphenolic lactone lacks the basic amine and is more planar/efflux-prone than the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Dicumarol reached less than 3% of plasma concentration in brain after intraperitoneal dosing; as a large bis-coumarin polyphenol without a basic amine, it is a weaker structural match for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query is a small, moderately lipophilic, weakly basic fused lactone-amine with a phenol; direct CNS-penetration evidence from structurally similar benzazepine/tetrahydroisoquinoline amines (SKF 38393, salsolinol, HMTIC) outweighs negative dye/polyphenol evidence that lacks the basic amine and is less transferable.",
  "evidence_gaps": [
    "No direct BBB or pharmacokinetic measurement exists for the query molecule itself.",
    "Efflux-transporter substrate status (P-gp/BCRP) of the query is unknown.",
    "Human CNS exposure data are unavailable; extrapolation relies on rat/mouse and human CSF analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

